import{z as p,x as A,o as E,c as B,q as l,j as t,D as o,d as n,s,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"Dynamo 与反熵","description":"","frontmatter":{"title":"Dynamo 与反熵","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dynamo-anti-entropy.md","filePath":"cs/dynamo-anti-entropy.md","lastUpdated":1791063341000}'),d={name:"cs/dynamo-anti-entropy.md"};function m(C,a,D,u,f,h){const r=A("Mermaid");return E(),B("div",null,[a[2]||(a[2]=l('<h1 id="dynamo-与反熵" tabindex="-1">Dynamo 与反熵 <a class="header-anchor" href="#dynamo-与反熵" aria-label="Permalink to &quot;Dynamo 与反熵&quot;">​</a></h1><div class="epigraph"><p>始终可写：斜向法定人数把字节先落到提示节点，再用 Merkle 反熵与读修复把分叉收回来。</p><footer>—— 据 DeCandia et al., Dynamo: Amazon&#39;s Highly Available Key-value Store, SOSP 2007 整理</footer></div><p>上一课<a href="/cs/quorum-rw">Quorum</a>的严格相交在分区下会拒绝写。Dynamo 选<a href="/cs/cap-pacelc">PACELC</a>的 A 与 L。缺口是<strong>提示移交与修复</strong>：写没到「该在的」副本时，系统如何还不丢、如何终收敛。本课不重写 \\(R+W\\gt n\\) 的证明。后课 LWW 是收敛时的一种打结。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一致性哈希环上每个键 \\(N\\) 个偏好节点。协调者写 \\(W\\) 个、读 \\(R\\) 个。节点失败时 <strong>sloppy quorum</strong>：写进环上后面的活节点，并记 hinted handoff，对方回来再推。偏好集暂时不相交，线性一致放弃。缺口：愈合后如何发现不一致——不能靠全量扫描每次。</p><p>反熵：副本两两比较键的摘要。Merkle 树让子树哈希不同才下降，带宽随差异量而不是全量。读修复：读时发现版本分叉，把合并结果写回。二者一起逼近<a href="/cs/eventual-consistency">最终一致</a>的收敛。</p><p><span class="marginnote">SOSP 2007 论文把 N/R/W、向量时钟、sloppy、Merkle、gossip 成员放在同一系统里。本课抓反熵与提示，成员 gossip 点名。</span></p><p><span class="marginnote">sloppy quorum 直译「将就的法定人数」：本该落在 N 个偏好节点上的写，节点挂了就「将就」写到环上下一个活节点，先落住再说。类比快递：收件地址没人签收，先放邻居家并留张纸条（提示），住户回来再从邻居取走——这张纸条就是 hinted handoff。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写路径：协调者（可以是负载均衡选的任意节点）向偏好节点并行写，凑满 \\(W\\)（含提示）。读路径：凑 \\(R\\)，比版本。后台：反熵会话、提示重放、节点上环后的数据迁入。</p>',10)),(E(),t(i,null,{default:o(()=>[s(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20PUT%5B%22PUT%22%5D%20--%3E%20SQ%5B%22sloppy%20W%22%5D%0A%20%20SQ%20--%3E%20HINT%5B%22%E6%8F%90%E7%A4%BA%E8%8A%82%E7%82%B9%22%5D%0A%20%20HINT%20--%3E%20HH%5B%22handoff%20%E5%9B%9E%E5%AE%B6%22%5D%0A%20%20GET%5B%22GET%22%5D%20--%3E%20RR%5B%22%E8%AF%BB%E4%BF%AE%E5%A4%8D%22%5D%0A%20%20AE%5B%22Merkle%20%E5%8F%8D%E7%86%B5%22%5D%20--%3E%20CONV%5B%22%E6%94%B6%E6%95%9B%22%5D%0A%20%20RR%20--%3E%20CONV%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"成员变化用 gossip，不必每次写先跑共识配置——这与链式复制的配置主相反。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[n("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"向量时钟标并发写：不可比则保留多版本交给应用（购物车合并）。单时间戳 LWW 会静默丢一边——下一课专门钉这个坑。\\(R=1,W=1\\) 延迟最低，分叉最多；\\(R=W=2,N=3\\) 是常见折中，仍不是 ABD。",-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},"N/R/W 代个数：N=3、W=2 表示写只要 3 个副本里 2 个确认，坏一个照样能写；R=2 同理。但 sloppy 模式下两次写可能落到不相交的节点组上，读两次也拼不齐全历史——严格 quorum 的「R+W 大于 N 必相交」保证被松掉了，反熵后台就是给这个缺口清账的。")],-1)),a[7]||(a[7]=e("p",null,"反熵不是立即：窗口内读可旧。运维看到的「不一致」是时间与故障的函数。Merkle 树深度与键分区粒度影响比较轮次；树本身要与哈希环分段对齐，否则比较的不是同一键集。",-1)),(E(),t(i,null,{default:o(()=>[s(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20HA%5B%22%E5%89%AF%E6%9C%AC%20A%20%E7%9A%84%20Merkle%20%E6%A0%91%E6%A0%B9%E5%93%88%E5%B8%8C%22%5D%20--%3E%20CMP%7B%22%E6%A0%B9%E5%93%88%E5%B8%8C%E7%9B%B8%E5%90%8C%EF%BC%9F%22%7D%0A%20%20HB%5B%22%E5%89%AF%E6%9C%AC%20B%20%E7%9A%84%20Merkle%20%E6%A0%91%E6%A0%B9%E5%93%88%E5%B8%8C%22%5D%20--%3E%20CMP%0A%20%20CMP%20--%3E%7C%E7%9B%B8%E5%90%8C%7C%20SAME%5B%22%E5%AD%90%E6%A0%91%E5%85%A8%E5%90%8C%EF%BC%8C%E8%B7%B3%E8%BF%87%E8%BF%99%E6%AE%B5%E9%94%AE%E7%A9%BA%E9%97%B4%22%5D%0A%20%20CMP%20--%3E%7C%E4%B8%8D%E5%90%8C%7C%20DOWN%5B%22%E4%B8%8B%E9%99%8D%E4%B8%80%E5%B1%82%EF%BC%8C%E6%AF%94%E8%BE%83%E5%AD%90%E6%A0%91%E5%93%88%E5%B8%8C%22%5D%0A%20%20DOWN%20--%3E%20LEAF%5B%22%E5%AE%9A%E4%BD%8D%E5%88%B0%E5%B0%91%E6%95%B0%E4%B8%8D%E5%90%8C%E7%9A%84%E9%94%AE%EF%BC%8C%E5%8F%AA%E5%90%8C%E6%AD%A5%E8%BF%99%E4%BA%9B%E9%94%AE%22%5D%0A"})]),fallback:o(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=l('<p><span class="marginnote">Merkle 树比较可以类比「对答案」：先对总分（根哈希），总分一样整卷免查；不一样再按大题对分，只把分数不同的几道小题翻出来细看。同步的数据量取决于差异多少而不是全量——这就是正文「带宽随差异量」的意思。</span></p><p>本课不把 Cassandra/Riak 当新定理，它们是 Dynamo 论文的后裔。也不把对象存储的跨 AZ 异步复制写成 hinted handoff。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 CRDT 半格，不展开一致性哈希虚节点（数据结构课已有）。后课默认：AP 键值 = sloppy + 版本 + 反熵；严格相交的寄存器不要冒充 Dynamo。冲突如何自动消掉是 LWW 与 CRDT 的分界。</p><p>始终可写把安全债务推到愈合。债务用版本与反熵还，不用 CAP 口号还。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Sloppy quorum 与提示移交换可用性，放弃读写相交。</li><li>Merkle 反熵与读修复驱动收敛。</li><li>并发写靠版本向量检出，合并规则另课。</li><li>出处：DeCandia et al., SOSP 2007。</li></ul>',7))])}const P=p(d,[["render",m]]);export{c as __pageData,P as default};
